const http = require('http');
const fs = require('fs');
const path = require('path');
const {spawn} = require('child_process');
const base = path.resolve('connect-plus-free');
const server = http.createServer((req,res) => {
  const file = path.join(base, decodeURIComponent(req.url.split('?')[0]));
  fs.readFile(file, (err,data) => {
    if (err) {res.writeHead(404); res.end(); return;}
    const mime = {'.html':'text/html','.css':'text/css','.js':'text/javascript','.svg':'image/svg+xml','.png':'image/png'};
    res.setHeader('Content-Type', mime[path.extname(file)] || 'application/octet-stream'); res.end(data);
  });
});
(async()=>{
 await new Promise(r=>server.listen(8765,'127.0.0.1',r));
 const chrome=spawn('C:/Program Files/Google/Chrome/Application/chrome.exe', ['--headless=new','--no-first-run','--no-default-browser-check','--remote-debugging-port=9223',`--user-data-dir=${process.env.TEMP}/connect-plus-layout-check`,'about:blank'],{stdio:'ignore'});
 let ws;
 try {
   let tabs;
   for(let i=0;i<10;i++) { try {tabs=await (await fetch('http://127.0.0.1:9223/json',{signal:AbortSignal.timeout(1000)})).json();break;}catch {await new Promise(r=>setTimeout(r,300));} }
   if(!tabs) throw Error('Headless browser unavailable');
   ws=new WebSocket(tabs.find(t=>t.type==='page').webSocketDebuggerUrl); await new Promise(r=>ws.onopen=r);
   let id=0; const pending=new Map();
   ws.onmessage=e=>{const m=JSON.parse(e.data); if(m.id){pending.get(m.id)?.(m);pending.delete(m.id);}};
   const call=(method,params={})=>new Promise((resolve,reject)=>{const n=++id;pending.set(n,m=>m.error?reject(m.error):resolve(m.result));ws.send(JSON.stringify({id:n,method,params}));});
   const evaluate=async expression=>(await call('Runtime.evaluate',{expression,returnByValue:true})).result.value;
   await call('Page.enable');
   for(const tree of ['src','dist']) for(const width of [320,390,768,1024,1440]) {
     await call('Emulation.setDeviceMetricsOverride',{width,height:1000,deviceScaleFactor:1,mobile:false});
     await call('Page.navigate',{url:`http://127.0.0.1:8765/${tree}/index.html`});
     await new Promise(r=>setTimeout(r,1300));
     console.log(tree,width,await evaluate(`JSON.stringify({font:getComputedStyle(document.body).fontFamily,overflow:[...document.querySelectorAll('.main-panel,.card,.navbar-menu-wrapper,.dashboard-filters')].filter(e=>{let r=e.getBoundingClientRect();return r.right>innerWidth+1||r.left< -1}).map(e=>e.className),brokenImages:[...document.images].filter(e=>!e.complete||!e.naturalWidth).map(e=>e.getAttribute('src'))})`));
     if(width===390){
       await evaluate(`document.querySelector('[data-toggle="offcanvas"]').click()`);
       await new Promise(r=>setTimeout(r,350));
       console.log('menu',await evaluate(`JSON.stringify({expanded:document.querySelector('[data-toggle="offcanvas"]').getAttribute('aria-expanded'),top:document.querySelector('#sidebar').getBoundingClientRect().top,navBottom:document.querySelector('.navbar').getBoundingClientRect().bottom})`));
       await evaluate(`document.querySelector('[data-toggle="offcanvas"]').click();document.querySelector('#bannerClose').click()`);
       console.log('dismiss',await evaluate(`JSON.stringify({navBottom:document.querySelector('.navbar').getBoundingClientRect().bottom,contentTop:document.querySelector('.content-wrapper').getBoundingClientRect().top})`));
     }
     if(tree==='src' && [390,1440].includes(width)) { await new Promise(r=>setTimeout(r,400)); const shot=await call('Page.captureScreenshot',{format:'png'});fs.writeFileSync(`${process.env.TEMP}/connect-plus-${width}.png`,Buffer.from(shot.data,'base64')); }
   }
   for(const page of ['forms/basic_elements','tables/basic-table','samples/login','ui-features/buttons']) {
     await call('Emulation.setDeviceMetricsOverride',{width:390,height:1000,deviceScaleFactor:1,mobile:false});
     await call('Page.navigate',{url:`http://127.0.0.1:8765/src/pages/${page}.html`});await new Promise(r=>setTimeout(r,500));
     console.log(page,await evaluate(`JSON.stringify({overflow:[...document.querySelectorAll('.card,.auth-form-light,.main-panel')].filter(e=>e.getBoundingClientRect().right>innerWidth+1).map(e=>e.className)})`));
   }
   await call('Browser.close');
 }finally {ws?.close();chrome.kill();server.close();}
})().catch(e=>{console.error(e);process.exitCode=1;});

