const fs = require('fs');
const path = require('path');
const root = 'connect-plus-free';
const font = '"Segoe UI", system-ui, -apple-system, BlinkMacSystemFont, Arial, sans-serif';
const responsive = fs.readFileSync(`${root}/src/assets/scss/shared/_responsive.scss`, 'utf8');
const edit = (file, fn) => fs.writeFileSync(file, fn(fs.readFileSync(file, 'utf8')));
edit(`${root}/src/assets/scss/light/_variables.scss`, s => s.replace(/'nunito-(?:light|regular|medium|bold)',\s*sans-serif/g, font));
edit(`${root}/src/assets/scss/vertical-light-layout/style.scss`, s => s + '\n@import "../shared/responsive";\n');
for (const tree of ['src', 'dist']) {
  const base = `${root}/${tree}`;
  edit(`${base}/assets/css/vertical-light-layout/style.css`, s => s.replace(/"nunito-(?:light|regular|medium|bold)",\s*sans-serif/g, font) + '\n' + responsive);
